// SPDX-License-Identifier: MIT

/**
 * \file bench_framework.h
 * \brief Reusable timing and statistics primitives for the unified
 *        liboqs benchmark framework (bench_unified).
 *
 * The framework deliberately uses fixed-iteration batches with a warmup
 * phase and several repeated batches.  Reporting the median of the batch
 * throughputs yields numbers that stay stable across runs on the same
 * machine with the same parameters, which is what the reproducibility
 * acceptance check relies on.
 */

#ifndef OQS_BENCH_FRAMEWORK_H
#define OQS_BENCH_FRAMEWORK_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/** Monotonic timestamp in nanoseconds; 0 only if no timer is available. */
uint64_t bench_time_ns(void);

/** Prevent the compiler from eliminating writes to @p p. */
void bench_escape(const void *p);

typedef struct bench_sample {
	uint64_t elapsed_ns;
	double ops_per_sec;
} bench_sample;

typedef struct bench_stats {
	size_t count;
	double median_ops_per_sec;
	double mean_ops_per_sec;
	double stdev_ops_per_sec;
	double min_ops_per_sec;
	double max_ops_per_sec;
	double cv_percent;
	double median_ns_per_op;
} bench_stats;

void bench_stats_compute(const bench_sample *samples, size_t count, size_t iterations, bench_stats *stats);

/** Convert bytes + median throughput to decimal MB/s (1 MB = 1e6 bytes). */
double bench_bytes_per_sec_to_mb_s(double ops_per_sec, size_t bytes_per_op);

#ifdef __cplusplus
}
#endif

#endif
