+	FILE *out = stdout;
+	if (cfg.output_path != NULL) {
+		out = fopen(cfg.output_path, "w");
+		if (out == NULL) {
+			fprintf(stderr, "bench_unified: cannot open output file '%s'\n", cfg.output_path);
+			OQS_destroy();
+			return EXIT_FAILURE;
